_choice_bool() {
    printf 'true\nfalse\n'
}

_choice_color() {
    printf '%s\n' black red green yellow blue magenta cyan white default \
        light_black light_red light_green light_yellow light_blue light_magenta light_cyan light_white
}

_choice_config() {
    fastfetch --list-presets 2>/dev/null | gawk '
        /^[^[:space:]].*\.jsonc$/ {
            sub(/\.jsonc$/, "")
            print
        }'
    _argc_util_comp_path
}

_choice_enum() {
    [[ -n "${argc__option:-}" ]] || return 0
    local option="${argc__option#argc_}"
    option="${option//_/-}"
    fastfetch -h "$option" 2>/dev/null | gawk '
        /^[[:space:]]*Options:[[:space:]]*$/ {
            in_options = 1
            next
        }
        in_options && /^[[:space:]]*Remark:/ {
            exit
        }
        in_options {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            if (line == "") {
                next
            }
            key = line
            sub(/[[:space:]]*:.*/, "", key)
            desc = line
            sub(/^[^:]*:[[:space:]]*/, "", desc)
            printf "%s\t%s\n", key, desc
        }'
}

_choice_help() {
    fastfetch --help 2>/dev/null | gawk '
        /^[[:space:]]+-/ {
            if (match($0, /--[A-Za-z0-9-]+/)) {
                name = substr($0, RSTART + 2, RLENGTH - 2)
                if (name !~ /-$/) {
                    print name
                }
            }
        }'
}

_choice_logo() {
    printf 'none\tDisable logo output\n'
    fastfetch --list-logos 2>/dev/null | gawk '
        /^[0-9]+\)/ {
            line = $0
            sub(/^[0-9]+\)[[:space:]]*/, "", line)
            while (match(line, /"[^"]*"/)) {
                print substr(line, RSTART + 1, RLENGTH - 2)
                line = substr(line, RSTART + RLENGTH)
            }
        }'
    _argc_util_comp_path
}

_choice_structure() {
    fastfetch --list-modules 2>/dev/null | gawk '
        /^[0-9]+\)/ {
            line = $0
            sub(/^[0-9]+\)[[:space:]]*/, "", line)
            key = line
            sub(/[[:space:]]*:.*/, "", key)
            desc = line
            sub(/^[^:]*:[[:space:]]*/, "", desc)
            printf "%s\t%s\n", key, desc
        }' | _argc_util_comp_multi :
}
